arduino.setup:
Serial.begin(9600);
pinMode(9, OUTPUT);
pinMode(10, INPUT);
Serial.println("HC-SR04 Ready");

arduino.loop:
digitalWrite(9, LOW);
delayMicroseconds(2);
digitalWrite(9, HIGH);
delayMicroseconds(10);
digitalWrite(9, LOW);
long dur = pulseIn(10, HIGH);
float cm = dur / 58.2;
float inch = dur / 148.0;
Serial.print("Distance: ");
Serial.print(cm, 1);
Serial.print(" cm | ");
Serial.print(inch, 1);
Serial.println(" in");
delay(500);
